// Resolve the mirror spreadsheet by name so no document id is ever pasted into a
// node -- the sheet can be deleted and recreated without touching this workflow.
//
// Exactly one match, or fail loudly. Zero means the sheet was renamed, trashed, or
// never shared with the service account. More than one means the name is ambiguous,
// and picking either could write lead PII into the wrong document -- so refuse rather
// than guess. `Find Sheet` sets alwaysOutputData so the zero case still reaches here;
// without it this node would not run at all and the sync would silently do nothing.
const want = $env.lead_sheet_name ?? 'Prudentia Leads Mirror';
const hits = $input.all().filter((i) => i.json && i.json.id);

if (hits.length !== 1) {
  throw new Error(
    `Sheet mirror: expected exactly 1 Drive spreadsheet named "${want}", found ${hits.length}. ` +
    'Check the name, that it is not in the trash, and that it is shared with the ' +
    'service account as Editor.'
  );
}

return [{ json: { sheet_id: hits[0].json.id, sheet_name: hits[0].json.name } }];
